#include "rigid.hpp"
#include <fstream>
#include <iostream>
#include <iomanip>
#include <filesystem>
#include <sstream>
#include <omp.h>
using namespace rigid;
int main(){std::filesystem::create_directories("modal_transfer");Model m;m.count=3;m.dim=2;m.rigid=true;m.mass=V::Ones(3);m.length=V::Ones(3);m.stiffness=V::Zero(3);m.gravity=vec({0,-9.81});Mat A=angle_mass(m,V::Zero(3)),K=(9.81*suffix(m)).asDiagonal();Eigen::GeneralizedSelfAdjointEigenSolver<Mat>eig(K,A);V freq=eig.eigenvalues().cwiseSqrt();Mat basis=eig.eigenvectors();V z=V::Zero(6);z.head(3)=.02*basis.col(2)+2e-7*basis.col(0);State initial=cartesian(m,z);Scale scale=scales(m,initial);double h=1./30,e0=energy(m,initial);int steps=1800;std::vector<State>refs{initial};V ref=z,ref2=z;double gap=0;std::ofstream rf("modal_transfer/reference.csv");rf<<std::setprecision(16)<<"t,mode0_energy,mode1_energy,mode2_energy,relative_energy,x0,x1,x2,x3,x4,x5\n";for(int i=0;i<steps;++i){ref=rk4(m,ref,h,32);ref2=rk4(m,ref2,h,64);refs.push_back(cartesian(m,ref2));gap=std::max(gap,(encode(cartesian(m,ref),scale)-encode(refs.back(),scale)).norm());V a=basis.transpose()*A*ref2.head(3),v=basis.transpose()*A*ref2.tail(3);rf<<(i+1)*h;for(int k=0;k<3;++k)rf<<","<<(freq[k]*freq[k]*a[k]*a[k]+v[k]*v[k])/(freq[2]*freq[2]*.02*.02);rf<<","<<(energy(m,refs.back())-e0)/scale.e;for(double v:refs.back().x)rf<<","<<v;rf<<"\n";}
std::vector<std::string>methods={"obj_midpotential_b1","obj_quarter_b1","canonical_dg","sym_energy"};for(double c:{0.,.5,1.,1.5,2.})for(double b:{.1,1.,10.})methods.push_back("obj_reaction"+std::to_string(c)+"_b"+std::to_string(b));std::vector<std::string>rows(methods.size());
#pragma omp parallel for schedule(dynamic)
for(int j=0;j<int(methods.size());++j){std::string meth=methods[j];State s=initial;double maxE=0,maxLeak=0,minMain=1,maxMain=0,maxT=0,sum=0;int done=0;std::string status="complete",reason;std::ofstream f("modal_transfer/"+meth+".csv");f<<std::setprecision(16)<<"t,mode0_energy,mode1_energy,mode2_energy,relative_energy,tangency";for(int k=0;k<6;++k)f<<",x"<<k;f<<"\n";for(int i=0;i<steps;++i){Result a=advance(m,s,h,scale,meth);if(!a.ok){status="failed";reason=a.reason;break;}s=a.s;++done;V zz=angles(m,s),amps=basis.transpose()*A*zz.head(3),vel=basis.transpose()*A*zz.tail(3),energies=(freq.array().square()*amps.array().square()+vel.array().square())/(freq[2]*freq[2]*.02*.02);double ee=(energy(m,s)-e0)/scale.e,tt=(gradient(m,s.x)*s.v).norm()/(scale.l*scale.v);maxE=std::max(maxE,std::abs(ee));maxLeak=std::max(maxLeak,energies[0]+energies[1]);minMain=std::min(minMain,energies[2]);maxMain=std::max(maxMain,energies[2]);maxT=std::max(maxT,tt);sum+=(s.x-refs[i+1].x).squaredNorm()/3;f<<(i+1)*h;for(int k=0;k<3;++k)f<<","<<energies[k];f<<","<<ee<<","<<tt;for(double v:s.x)f<<","<<v;f<<"\n";}std::ostringstream o;o<<std::setprecision(16)<<meth<<","<<status<<","<<reason<<","<<done<<","<<steps<<","<<maxE<<","<<maxLeak<<","<<minMain<<","<<maxMain<<","<<maxT<<","<<std::sqrt(sum/std::max(done,1))<<","<<gap;rows[j]=o.str();}
std::ofstream f("modal_transfer/summary.csv");f<<"method,status,reason,steps_done,steps_requested,max_energy_relative,max_other_mode_fraction,min_main_mode_fraction,max_main_mode_fraction,max_tangency,position_rms,reference_gap\n";for(auto&r:rows)f<<r<<"\n";std::cout<<"transfer rows="<<rows.size()<<" reference_gap="<<gap<<"\n";
 // For linear gravitational U, omitting the old reaction in the quarter
 // predictor gives exactly the plain midpoint-potential objective up to a constant.
objectives2::Variant quarter={"quarter","quarter","soft_midpoint","constant","verlet",1,true,false},mid={"midpotential","midpotential","soft_midpoint","constant","verlet",1,true,false};objectives2::Objective p(m,initial,h,quarter,scale.e),r(m,initial,h,mid,scale.e);p.aold=masses(m).cwiseInverse().cwiseProduct(force(m,initial.x));V v=p.initial();for(int k=0;k<v.size();++k)v[k]+=.01*std::sin(k+1);auto ep=p.evaluate(v),er=r.evaluate(v);double gd=(ep.objective.g-er.objective.g).norm(),hd=(ep.objective.H-er.objective.H).norm();std::ofstream eq("reaction_equivalence.csv");eq<<"gradient_discrepancy,hessian_discrepancy\n"<<std::setprecision(16)<<gd<<","<<hd<<"\n";return gd<1e-8&&hd<1e-8?0:1;}
